import sys,numpy as np
sys.path.insert(0,'/app/output'); import gen
r=gen.observe(cameras=['robot_wrist'],depth=True); q=np.array(r.meta['proprio']['now'][6:13]); base=np.array(r.meta['proprio']['now'][:3]);axes=np.array(gen.SPEC['arm']['axis'],float);pts=np.array(gen.SPEC['arm']['position_m'],float);ee=np.array(gen.SPEC['arm']['end_effector']['position_m'],float)
R=np.eye(3);t=np.zeros(3)
for a,p,ang in zip(axes,pts,q):
 aw=R@a;pw=R@p+t;a=aw/np.linalg.norm(aw);K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]]);Ri=np.eye(3)+np.sin(ang)*K+(1-np.cos(ang))*(K@K);R=Ri@R;t=pw+Ri@(t-pw)
cam=R@np.array(gen.SPEC['cameras']['robot_wrist']['pose']['position_m'])+t;B=R@np.diag([-1,1,1]);im=r.last['robot_wrist'].astype(int);dep=r.depth['robot_wrist'][0];mask=(im[:,:,0]>im[:,:,1]*1.35+20)&(im[:,:,0]>im[:,:,2]*1.3+15)&(im[:,:,0]>55)&(np.indices(im.shape[:2])[0]<240); H,W=mask.shape; seen=np.zeros_like(mask); comps=[]
for yy,xx in zip(*np.where(mask)):
 if seen[yy,xx]:continue
 st=[(yy,xx)];seen[yy,xx]=1;arr=[]
 while st:
  y,x=st.pop();arr.append((y,x))
  for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
   ny,nx=y+dy,x+dx
   if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;st.append((ny,nx))
 if len(arr)>=40:
  ar=np.array(arr); cy,cx=ar.mean(0); comps.append((cy,cx,np.median(dep[ar[:,0],ar[:,1]]),len(ar)))
f=H/(2*np.tan(np.deg2rad(41.8)/2)); yaw=base[2]; Rot=np.array([[np.cos(yaw),-np.sin(yaw)],[np.sin(yaw),np.cos(yaw)]])
print('ee',R@ee+t,'cam',cam,'base',base)
for cy,cx,z,n in sorted(comps):
 X=(cx-W/2)*z/f;Y=(H/2-cy)*z/f; p=cam+B@np.array([X,Y,z]); print(round(cx,1),round(cy,1),round(z,3),'relative',np.round(p,3),'odom',np.round(base[:2]+Rot@p[:2],3))
